//! The heartbeats of the services a project's `trust.toml` declares (specification 48 RU-63): the
//! generated file, its refusals, and the build's check of the committed file.

use std::path::{Path, PathBuf};

use super::super::{check_services, layout, write_generated, Written, SERVICES_FILE};
use super::services_text;

/// A project folder holding `files`, each a path relative to it and its text.
fn project(files: &[(&str, &str)]) -> PathBuf {
    let root = trust_test_support::unique_temp_path("services");
    std::fs::create_dir_all(&root).expect("the project folder");
    for (path, text) in files {
        let file = root.join(path);
        std::fs::create_dir_all(file.parent().expect("a folder")).expect("the folder");
        std::fs::write(file, text).expect("the file");
    }
    root
}

/// Two services in an order that is not the alphabet's, with Appendix B's settings.
const TRUST_TOML: &str = "[services.recipe]
package = \"recipe-service\"
heartbeat = \"500ms\"
endpoint = \"tcp://127.0.0.1:47800\"
credentials = \"secrets/recipe.token\"

[services.camera]
package = \"camera-service\"
heartbeat = \"100ms\"
";

/// The generated file of [`TRUST_TOML`]'s services.
const SERVICES: &str = "(* GENERATED by trust-runtime from trust.toml - do not edit *)
VAR_GLOBAL
    recipe_heartbeat : UDINT;
    camera_heartbeat : UDINT;
END_VAR
";

#[test]
fn each_service_has_a_heartbeat_global_in_trust_tomls_order() {
    // RU-63: one VAR_GLOBAL holds `<name>_heartbeat : UDINT` for each `[services.<name>]`, in
    // `trust.toml`'s order, recipe before camera. Catches a service left out, the services sorted,
    // a heartbeat of another type, and a setting of a service written into the file.
    let root = project(&[("trust.toml", TRUST_TOML)]);
    assert_eq!(services_text(&root), Ok(Some((SERVICES.to_string(), 2))));
}

#[test]
fn a_project_without_services_has_no_heartbeats() {
    // RU-63, RU-07: a project without `trust.toml`, one whose `trust.toml` holds only `[rust]`, and
    // one with an empty `[services]` declare no service, so there is no file. Catches a file of no
    // variables, which would declare an empty VAR_GLOBAL in every project.
    for files in [
        vec![],
        vec![("trust.toml", "[rust]\ncrate = \"rust\"\n")],
        vec![("trust.toml", "[services]\n")],
    ] {
        assert_eq!(services_text(&project(&files)), Ok(None), "{files:?}");
    }
}

#[test]
fn a_service_trust_toml_cannot_hold_is_named() {
    // Appendix B, RU-63: a service whose name is no identifier, whose global could not be declared,
    // a `[services]` that is no table, and a service that is no table are refused at `trust.toml`
    // with their reasons. Catches a name written into the file that breaks it.
    for (text, named) in [
        (
            "[services.recipe-svc]\nheartbeat = \"500ms\"\n",
            "[services.recipe-svc]",
        ),
        ("[services.2nd]\nheartbeat = \"500ms\"\n", "[services.2nd]"),
        ("services = 3\n", "holds a table"),
        ("[services]\nrecipe = 3\n", "[services.recipe] is the table"),
    ] {
        let root = project(&[("trust.toml", text)]);
        let refused = services_text(&root).expect_err(text);
        assert!(refused.contains(named), "{text}: {refused}");
    }
}

#[test]
fn a_setting_appendix_b_does_not_list_is_refused_naming_it() {
    // Appendix B, RU-63: a service's settings are `package`, `heartbeat`, `writes`, `endpoint` and
    // `credentials`, and every one of them is taken; another key, a misspelt `heartbeat` or the
    // `timeout` that no requirement defines, refuses `trust.toml` naming the service and the key, as
    // runtime.toml refuses an unknown key. Catches a misspelt setting that is lost, so that the
    // service runs on the default it was meant to replace.
    let every = "[services.recipe]\npackage = \"recipe-service\"\nheartbeat = \"500ms\"\n\
                 writes = [\"Main.target\"]\nendpoint = \"tcp://127.0.0.1:47800\"\n\
                 credentials = \"secrets/recipe.token\"\n";
    let root = project(&[("trust.toml", every)]);
    assert!(
        services_text(&root).is_ok_and(|text| text.is_some()),
        "{every}"
    );
    for (text, key) in [
        ("[services.recipe]\nheartbaet = \"500ms\"\n", "`heartbaet`"),
        (
            "[services.camera]\nheartbeat = \"1s\"\ntimeout = \"2s\"\n",
            "`timeout`",
        ),
    ] {
        let root = project(&[("trust.toml", text)]);
        let refused = services_text(&root).expect_err(text);
        let service = text.lines().next().expect("the service's table");
        assert!(
            refused.contains(service) && refused.contains(key),
            "{text}: {refused}"
        );
    }
}

/// The text of the project's generated services file, `None` without one.
fn held(root: &Path) -> Option<String> {
    std::fs::read_to_string(root.join(SERVICES_FILE)).ok()
}

#[test]
fn the_heartbeats_are_written_and_checked_with_or_without_a_crate() {
    // RU-63, RU-24, RU-07: a Structured Text project without a crate whose `trust.toml` declares
    // services gets the file from `trust-dev rust declarations` (`write_generated`), which the build
    // then accepts; a `trust.toml` that loses its services makes the committed file out of date, so
    // the build refuses it naming the command, and the command removes the file. Catches heartbeats
    // written only for a project with a crate, a build that accepts a file trust.toml no longer
    // declares, and a file kept after its services are gone.
    let root = project(&[("trust.toml", TRUST_TOML)]);
    let layout = layout(&root).expect("the layout");
    assert_eq!(layout.services, SERVICES_FILE);
    assert!(check_services(&root, &layout).is_err_and(|refusal| {
        refusal.contains(SERVICES_FILE) && refusal.contains("trust-dev rust declarations")
    }));
    let generated = write_generated(&root).expect("the project writes");
    assert_eq!(generated.declarations, Written::Nothing);
    assert_eq!(generated.services, Written::Wrote(2));
    assert_eq!(held(&root).as_deref(), Some(SERVICES));
    assert_eq!(check_services(&root, &layout), Ok(()));
    let again = write_generated(&root).expect("the project writes");
    assert_eq!(again.services, Written::UpToDate);
    std::fs::write(root.join("trust.toml"), "[rust]\ncrate = \"rust\"\n").expect("trust.toml");
    assert!(check_services(&root, &layout).is_err());
    let removed = write_generated(&root).expect("the project writes");
    assert_eq!(removed.services, Written::Removed);
    assert_eq!(held(&root), None);
    assert_eq!(check_services(&root, &layout), Ok(()));
}

#[test]
fn a_rust_first_projects_heartbeats_lie_with_its_generated_text() {
    // RU-63, RU-65: a Rust-first project's file lies in `src/generated/trust/` beside the
    // declarations and the configuration. Catches it written where a Structured Text project's goes.
    let root = project(&[(
        "trust.toml",
        &format!("[rust]\ncrate = \".\"\n\n{TRUST_TOML}"),
    )]);
    let layout = layout(&root).expect("the layout");
    assert_eq!(layout.services, "src/generated/trust/services.st");
    write_generated(&root).expect("the project writes");
    assert_eq!(
        std::fs::read_to_string(root.join("src/generated/trust/services.st"))
            .ok()
            .as_deref(),
        Some(SERVICES)
    );
    assert_eq!(held(&root), None);
}
